+    public void testFanOutWithoutCancellation() {
+        final var task = randomFrom(
+            new Task(1, "test", "test", "", TaskId.EMPTY_TASK_ID, Map.of()),
+            new CancellableTask(1, "test", "test", "", TaskId.EMPTY_TASK_ID, Map.of()),
