+        Authorization: "Basic YWRtaW5fdXNlcjp4LXBhY2stdGVzdC1wYXNzd29yZA==" # admin_user
+      security.update_cross_cluster_api_key:
+        id: "$api_key_id"
+        body: >
+          {
+            "access": {
+              "replication": [
+                {
+                  "names": ["archive"]
+                }
+              ]
+            },
+            "metadata": { "tag": "prod" }
+          }
+  - match: { updated: false }
