+            assertArrayEquals(new int[] { 0, 1, 14, 4, 9, 10, 14, 6, 7, 8, 14, 14, 3, 5 }, tokenization.tokenIds());
+            assertArrayEquals(new int[] { 0, 1, 2, 3, 4, 4, 5, 6, 6, 6, 7, 8, 9, 10 }, tokenization.tokenMap());
