+    /** Grow a size by 1/8. */
+    static int oversize(int size) {
+        return size + (size >>> 3);
+    }
+
+    private final NodeAllocator nodeAllocator;
+    private int root;
+    private int[] parent;
+    private int[] left;
+    private int[] right;
+    private byte[] depth;
