+            final Map.Entry<Integer, Integer> next = it.next();
+            assertEquals(next.getKey().intValue(), bag.values[node]);
+            assertEquals(next.getValue().intValue(), bag.counts[node]);
+        }
+        assertFalse(it.hasNext());
+    }
+
+}
