+            double est = md.quantile(q);
+            double actual = Dist.quantile(q, raw);
+            double qx = md.cdf(actual);
+            Assert.assertEquals(q, qx, 0.5);
+            Assert.assertEquals(est, actual, 3.8);
+        }
+    }
