+        double[] data = new double[100];
+        for (int i = 0; i < data.length; i++) {
+            data[i] = Math.floor(gen.nextGaussian() * 3);
+        }
+        for (int i = 0; i < 100; i++) {
+            for (double x : data) {
+                d.add(x);
+            }
+        }
+        int last = 0;
+        for (Centroid centroid : d.centroids()) {
+            if (last == 0) {
+                assertEquals(1, centroid.count());
+            }
+            last = centroid.count();
+        }
+        assertEquals(1, last);
+    }
