+            }
+            double[] v0 = valuesFromKeys(keys, 0);
+            double[] v1 = valuesFromKeys(keys, 1);
+
+            Sort.sort(keys, 10, 10, v0, v1);
+            checkOrder(keys, 10, 10, v0, v1);
+            checkValues(keys, 0, keys.length, v0, v1);
+            for (int i = 0; i < 10; i++) {
+                assertEquals(i, keys[i], 0);
