+        double n = 3e9;
+        double q0 = 0;
+        for (int i = 0; i < 200 && q0 < 1 - 1e-10; ++i) {
+            double k0 = digest.scale.k(q0, digest.compression(), n);
+            double q = digest.scale.q(k0 + 1, digest.compression(), n);
+            int m = (int) Math.max(1, n * (q - q0));
+            digest.add((q + q0) / 2, m);
