+        }
+        digest.compress();
+        assertEquals(3_000_000_000L, digest.size());
+        assertTrue(digest.size() > Integer.MAX_VALUE);
+        final double[] quantiles = new double[] { 0, 0.1, 0.5, 0.9, 1 };
+        double prev = Double.NEGATIVE_INFINITY;
+        for (double q : quantiles) {
