+    /**
+     * Remove the specified node from the tree.
+     */
+    public void remove(int node) {
+        if (node == NIL) {
+            throw new IllegalArgumentException();
+        }
+        if (left(node) != NIL && right(node) != NIL) {
+            // inner node
+            final int next = next(node);
+            assert next != NIL;
+            swap(node, next);
+        }
+        assert left(node) == NIL || right(node) == NIL;
+
+        final int parent = parent(node);
+        int child = left(node);
+        if (child == NIL) {
+            child = right(node);
+        }
+
+        if (child == NIL) {
+            // no children
+            if (node == root) {
+                assert size() == 1 : size();
+                root = NIL;
+            } else {
+                if (node == left(parent)) {
+                    left(parent, NIL);
+                } else {
+                    assert node == right(parent);
+                    right(parent, NIL);
+                }
+            }
+        } else {
+            // one single child
+            if (node == root) {
+                assert size() == 2;
+                root = child;
+            } else if (node == left(parent)) {
+                left(parent, child);
+            } else {
+                assert node == right(parent);
+                right(parent, child);
+            }
+            parent(child, parent);
+        }
+
+        release(node);
+        rebalance(parent);
+    }
+
+    private void release(int node) {
+        left(node, NIL);
+        right(node, NIL);
+        parent(node, NIL);
+        nodeAllocator.release(node);
+    }
+
+    private void swap(int node1, int node2) {
+        final int parent1 = parent(node1);
+        final int parent2 = parent(node2);
+        if (parent1 != NIL) {
+            if (node1 == left(parent1)) {
+                left(parent1, node2);
+            } else {
+                assert node1 == right(parent1);
+                right(parent1, node2);
+            }
+        } else {
+            assert root == node1;
+            root = node2;
+        }
+        if (parent2 != NIL) {
+            if (node2 == left(parent2)) {
+                left(parent2, node1);
+            } else {
+                assert node2 == right(parent2);
+                right(parent2, node1);
+            }
+        } else {
+            assert root == node2;
+            root = node1;
+        }
+        parent(node1, parent2);
+        parent(node2, parent1);
+
+        final int left1 = left(node1);
+        final int left2 = left(node2);
+        left(node1, left2);
+        if (left2 != NIL) {
+            parent(left2, node1);
+        }
+        left(node2, left1);
+        if (left1 != NIL) {
+            parent(left1, node2);
+        }
+
+        final int right1 = right(node1);
+        final int right2 = right(node2);
+        right(node1, right2);
+        if (right2 != NIL) {
+            parent(right2, node1);
+        }
+        right(node2, right1);
+        if (right1 != NIL) {
+            parent(right1, node2);
+        }
+
+        final int depth1 = depth(node1);
+        final int depth2 = depth(node2);
+        depth(node1, depth2);
+        depth(node2, depth1);
+    }
+
+    private int balanceFactor(int node) {
+        return depth(left(node)) - depth(right(node));
+    }
+
