+                    // nor too few. This is where issue #151 shows up
+                    label = String.format(Locale.ROOT, "min diff: %.3f, scale: %s, compression: %.0f, n: %d", diff, k, compression, n);
+                    assertTrue(label, diff >= Math.min(n, compression / 4));
+                }
+            }
+        }
+    }
