+        for (int i = 0; i < n; i++) {
+            int k = ((i + 5) * 37) % n;
+            values[i] = Math.floor(k / (double) z);
+            weights[i] = (k % z) + 1;
+            totalWeight += weights[i];
+        }
+
+        // verify: test weights should be evenly distributed
+        double[] tmp = new double[n / z];
+        for (int i = 0; i < n; i++) {
+            tmp[(int) values[i]] += weights[i];
+        }
+        for (double v : tmp) {
+            assertEquals(totalWeight / tmp.length, v, 0);
+        }
