+        for (int i = start; i < end; i++) {
+            assertEquals(value, values[order[i]], 0);
+            double newOrderedWeight = weights[order[i]] * ordering;
+            assertTrue(newOrderedWeight >= lastWeight);
+            lastWeight = newOrderedWeight;
+            sofar += weights[order[i]];
+        }
+        return sofar;
+    }
